let route=S.complete?'explore':'welcome',step=0,mode='solo',deckIndex=0,selectedFood='tofu',previous='explore',filterDraft,toastTimer,loadTimer,spinTimer,spinning=false,rotation=0,selectedAvatar=S.avatar,calendarMonth=new Date().getMonth(),calendarYear=new Date().getFullYear(),selectedDate=localDate(new Date()),mealDraft,avatarCategory='All',aiQuery='',resultSort='rating',savedCategory='All',prefReturn='explore';
